import{_ as e,a as r,b as t,c as o,d as s,e as n}from"./chunks/make-sticker.BPNaJpO6.js";import{_ as i,o as p,c as g,a2 as l}from"./chunks/framework.Bzj1XTnB.js";const b=JSON.parse('{"title":"Make a movie, stickers and sharing","description":"Export MP4, GIF or PNG frames, make WhatsApp stickers, and share or back up whole projects.","frontmatter":{"lang":"en","slug":"export-and-share","order":9,"title":"Make a movie, stickers and sharing","description":"Export MP4, GIF or PNG frames, make WhatsApp stickers, and share or back up whole projects."},"headers":[],"relativePath":"export-and-share.md","filePath":"export-and-share.md"}'),h={name:"export-and-share.md"};function c(d,a,m,k,u,f){return p(),g("div",null,[...a[0]||(a[0]=[l('<h1 id="make-a-movie-stickers-and-sharing" tabindex="-1">Make a movie, stickers and sharing <a class="header-anchor" href="#make-a-movie-stickers-and-sharing" aria-label="Permalink to &quot;Make a movie, stickers and sharing&quot;">​</a></h1><h2 id="make-a-movie" tabindex="-1">Make a movie <a class="header-anchor" href="#make-a-movie" aria-label="Permalink to &quot;Make a movie&quot;">​</a></h2><p>Tap the <strong>pink share arrow</strong> at the top of the editor, or <strong>Make movie</strong> in the <strong>⋮</strong> menu.</p><p><img src="'+e+'" alt="Make movie"></p><ul><li><p><strong>Movie name</strong></p></li><li><p><strong>Output size</strong> — <strong>Original</strong> (the canvas size), <strong>1080p</strong>, <strong>720p</strong>, <strong>480p</strong>, <strong>Square 1080</strong>, <strong>Vertical</strong> (1080 × 1920) or <strong>Custom</strong>.</p></li><li><p><strong>Format</strong>:</p><p><img src="'+r+'" alt="Formats"></p><ul><li><strong>MP4</strong> — a video with sound. Best for sharing on YouTube, Instagram, WhatsApp.</li><li><strong>GIF</strong> — an animated picture. Can have a see-through background. Choose <strong>Loop forever</strong> and <strong>Dithering</strong> (smoother colours).</li><li><strong>PNG Sequence</strong> — every frame as a picture in a zip file, for video editing apps.</li></ul></li><li><p><strong>Transparent background</strong> — GIF and PNG only.</p></li><li><p><strong>Watermark</strong> — a small Toonik logo in the corner. Off unless you turn it on.</p></li><li><p><strong>Include audio</strong> — MP4 only, when the project has sound.</p></li></ul><p>Tap <strong>Make movie</strong>. When it is ready you can <strong>Share</strong> it, <strong>Save to gallery</strong>, or tap <strong>Done</strong>.</p><p><img src="'+t+'" alt="Your movie is ready"></p><p>Your movies are kept in the <strong>Movies</strong> tab on the home screen. Tap one to play it, share it, save it to your gallery or delete it.</p><p><img src="'+o+'" alt="Movies tab"></p><p><img src="'+s+'" alt="Playing a movie"></p><h2 id="make-a-whatsapp-sticker" tabindex="-1">Make a WhatsApp sticker <a class="header-anchor" href="#make-a-whatsapp-sticker" aria-label="Permalink to &quot;Make a WhatsApp sticker&quot;">​</a></h2><p>Open <strong>⋮ → Make sticker</strong>. Your animation becomes an animated WhatsApp sticker.</p><p><img src="'+n+'" alt="Make a sticker"></p><ol><li>Pick up to three <strong>Emoji</strong> — WhatsApp suggests your sticker when someone types one of them.</li><li>Choose a <strong>Pack</strong>, or type a name to start a new one.</li><li>Tap <strong>Make sticker</strong>.</li></ol><p>Toonik frames the sticker around your drawing, so even a small doodle fills it. Stickers are 512 × 512 and under 500 KB, so long animations may lose some frames.</p><p><strong>WhatsApp needs at least 3 stickers in a pack</strong> before it can be added. Until then the pack says how many more it needs. When it is ready, tap <strong>Add to WhatsApp</strong>. Packs already in WhatsApp show <strong>Added</strong>; with WhatsApp Business installed too, you can also <strong>Add to Business</strong>. A pack holds up to 30 stickers.</p><h2 id="share-a-single-frame" tabindex="-1">Share a single frame <a class="header-anchor" href="#share-a-single-frame" aria-label="Permalink to &quot;Share a single frame&quot;">​</a></h2><p>Long-press a frame in the frame strip and tap <strong>Share</strong> to send that drawing as a picture.</p><h2 id="share-or-back-up-a-whole-project" tabindex="-1">Share or back up a whole project <a class="header-anchor" href="#share-or-back-up-a-whole-project" aria-label="Permalink to &quot;Share or back up a whole project&quot;">​</a></h2><p>On the home screen, long-press a project and tap <strong>Export project</strong>. You get a <code>.flippa</code> file: send it to a friend, keep it as a backup, or open it on another phone with <strong>⋮ → Import project</strong>.</p>',20)])])}const y=i(h,[["render",c]]);export{b as __pageData,y as default};
